import json
import gzip

# Read the trace file
with gzip.open("/tmp/1774357837.7396739-TP-0.trace.json.gz", "rt") as f:
    data = json.load(f)

events = data.get("traceEvents", [])

# Collect GPU kernel times
gpu_kernels = {}
for e in events:
    if e.get("cat") == "kernel":
        name = e["name"]
        dur = e.get("dur", 0)  # microseconds
        gpu_kernels[name] = gpu_kernels.get(name, 0) + dur

total = sum(gpu_kernels.values())
print(f"Total GPU kernel time: {total/1e6:.2f}s\n")
print("=== Top 30 GPU Kernels ===")
for name, dur in sorted(gpu_kernels.items(), key=lambda x: -x[1])[:30]:
    pct = dur / total * 100 if total else 0
    print(f"  {pct:5.1f}%  {dur/1000:8.1f}ms  {name}")

# Categorize kernels
categories = {"gemm": 0, "attention": 0, "elementwise": 0, "other": 0}
for name, dur in gpu_kernels.items():
    name_lower = name.lower()
    if any(x in name_lower for x in ["gemm", "matmul", "dot", "blas"]):
        categories["gemm"] += dur
    elif any(x in name_lower for x in ["attention", "softmax", "qkv", "flash"]):
        categories["attention"] += dur
    elif any(x in name_lower for x in ["norm", "silu", "gelu", "add", "mul", "copy", "kernel"]):
        categories["elementwise"] += dur
    else:
        categories["other"] += dur

print("\n=== Kernel Categories ===")
for cat, dur in sorted(categories.items(), key=lambda x: -x[1]):
    pct = dur / total * 100 if total else 0
    print(f"  {cat}: {pct:5.1f}%  {dur/1e6:.2f}s")
